export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ParseError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = words.slice(1)
      if (names.length === 0) {
        throw new ParseError(lineNumber, 'expected candidates <name>...')
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(lineNumber, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNumber, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      for (const name of names) candidateSet.add(name)
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const rest = words.slice(1)
      if (rest.length < 2) {
        throw new ParseError(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countText = rest[0]
      if (!COUNT_RE.test(countText)) {
        throw new ParseError(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countText)
      const preferences = rest.slice(1)
      const seen = new Set()
      for (const name of preferences) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, preferences })
    } else {
      throw new ParseError(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates, ballots }
}

export { ParseError }
