 * Runs the instant-runoff count for a parsed election, returning every round
 * counted and the eventual winner (or null when no candidate ever reaches a
 * majority of the active ballots).
 */

function breakTie(tied, history) {
  if (tied.length === 1) return tied[0]

  const numRounds = history.get(tied[0]).length
  for (let r = 0; r < numRounds; r++) {
    const values = tied.map((name) => history.get(name)[r])
    if (values.some((v) => v !== values[0])) {
      const minValue = Math.min(...values)
      const survivors = tied.filter((name) => history.get(name)[r] === minValue)
      return breakTie(survivors, history)
    }
  }

  // Every round counted so far ties these candidates exactly: fall back to
  // the name that sorts last by code point.
  return tied.slice().sort().pop()
}

export function runElection({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))
  const totalBallots = ballots.reduce((sum, b) => sum + b.count, 0)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map(Array.from(continuing).map((name) => [name, 0]))
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.preferences.find((name) => continuing.has(name))
      if (pick === undefined) exhausted += ballot.count
      else counts.set(pick, counts.get(pick) + ballot.count)
    }

    const activeTotal = totalBallots - exhausted
    for (const name of continuing) history.get(name).push(counts.get(name))

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    let roundWinner = null
    for (const name of continuing) {
      if (counts.get(name) * 2 > activeTotal) {
        roundWinner = name
        break
      }
    }

    if (roundWinner !== null) {
      winner = roundWinner
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    let min = Infinity
    for (const name of continuing) min = Math.min(min, counts.get(name))
    const tied = Array.from(continuing).filter((name) => counts.get(name) === min)
    const eliminated = breakTie(tied, history)

    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

