/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function formatRound({ counts, exhausted }) {
  const entries = Array.from(counts.entries()).sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return parts.join(' ')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = require_readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write(`${error.message}\n`)
      process.exit(2)
    }
    throw error
  }

  const { rounds, winner } = runElection(election)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      output.push(`round ${index + 1}: ${formatRound(round)}`)
      if (round.eliminated !== null) output.push(`eliminated ${round.eliminated}`)
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

function require_readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

main()
"}

